style.css:
@-moz-document domain("youtube.com") {
/* MBAPPE KM9 - RGB ULTRA 4K */

html, body, ytd-app {
  background: transparent !important;
}

/* FONDO MBAPPE 4K */
ytd-app::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    linear-gradient(
      90deg,
      rgba(0,0,10,.26),
      rgba(0,0,15,.46)
    ),
    url("https://4kwallpapers.com/images/wallpapers/kylian-mbappe-real-3840x2160-27350.jpg");
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
}

/* MOSTRAR FOTO POR DETRAS */
ytd-app,
#content,
#page-manager,
ytd-browse,
ytd-watch-flexy,
ytd-two-column-browse-results-renderer,
ytd-rich-grid-renderer,
#primary,
#secondary,
#columns {
  background-color: transparent !important;
}

#content.ytd-app,
#page-manager {
  position: relative;
  z-index: 1;
}

/* BARRA SUPERIOR OSCURA */
ytd-masthead,
#masthead-container {
  background: rgba(5,8,25,.88) !important;
  backdrop-filter: blur(13px) !important;
  border-bottom: 2px solid #00eaff !important;
  box-shadow: 0 0 20px #00eaff88 !important;
}

/* MENU LATERAL */
ytd-guide-renderer,
ytd-mini-guide-renderer,
tp-yt-app-drawer {
  background: rgba(5,8,25,.86) !important;
  backdrop-filter: blur(12px) !important;
}

/* KM9 EN LA PARTE SUPERIOR */
ytd-masthead #logo::after {
  content: "? KM9";
  display: inline-block;
  margin-left: 14px;
  font-size: 23px;
  font-weight: 1000;
  letter-spacing: 3px;
  color: #ffdf36;
  text-shadow:
    0 0 6px #fff,
    0 0 12px #ffcc00,
    0 0 25px #ff8800,
    0 0 40px #ffcc00;
  animation: kmPulse 2s infinite alternate;
}

@keyframes kmPulse {
  from { filter: brightness(1); }
  to { filter: brightness(1.8); }
}

/* SEARCH BAR RGB GIGANTE */
ytd-searchbox,
yt-searchbox,
.ytSearchboxComponentHost {
  position: relative !important;
  border-radius: 28px !important;
  background: rgba(4,7,23,.93) !important;
  box-shadow:
    0 0 8px #ff0044,
    0 0 16px #00ff88,
    0 0 28px #009dff,
    0 0 42px #ae00ff !important;
  animation: rgbChristmas 2s linear infinite !important;
}

/* RGB QUE CAMBIA CONSTANTEMENTE */
@keyframes rgbChristmas {
  0% {
    box-shadow:
      0 0 10px red,
      0 0 23px red,
      0 0 43px #ff00aa;
  }
  25% {
    box-shadow:
      0 0 10px lime,
      0 0 23px lime,
      0 0 43px cyan;
  }
  50% {
    box-shadow:
      0 0 10px cyan,
      0 0 23px blue,
      0 0 43px #00eeff;
  }
  75% {
    box-shadow:
      0 0 10px #ffee00,
      0 0 23px #ff00ff,
      0 0 43px #9900ff;
  }
  100% {
    box-shadow:
      0 0 10px red,
      0 0 23px red,
      0 0 43px #ff00aa;
  }
}

/* TEXTOS BLANCOS */
#video-title,
#channel-name,
#title,
#metadata-line,
yt-formatted-string {
  color: #fff !important;
  text-shadow: 0 1px 3px #000;
}

/* MINIATURAS NEON */
ytd-thumbnail img,
yt-thumbnail-view-model img {
  border-radius: 15px !important;
  transition: .3s ease !important;
}

ytd-rich-grid-media:hover ytd-thumbnail,
ytd-video-renderer:hover ytd-thumbnail {
  filter:
    drop-shadow(0 0 9px #00eeff)
    drop-shadow(0 0 13px #ae00ff);
}

/* BARRA DE VIDEO RGB */
.ytp-play-progress {
  background: linear-gradient(
    90deg,
    red, yellow, lime, cyan, blue, magenta
  ) !important;
}

/* SCROLL RGB */
::-webkit-scrollbar {
  width: 10px;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(
    red, yellow, lime, cyan, blue, magenta
  );
  border-radius: 20px;
}
}
